//! Shared test helper module.
//!
//! Resolves the monorepo workspace root (the directory containing
//! `pnpm-workspace.yaml`) by walking up from `CARGO_MANIFEST_DIR`, then
//! exposes absolute paths to the cross-language fixtures generated by
//! spec 037:
//!
//! - `packages/test-fixtures-sdk-parity/fixtures/parity-corpus.json`
//! - `packages/test-fixtures-sdk-parity/fixtures/parity-configs.json`
//! - `packages/test-fixtures-sdk-parity/fixtures/cache-key-fixtures.json`
//! - `packages/test-fixtures-sdk-parity/fixtures/sdk-key-shapes.json`
//!
//! The walk happens once at first call via `OnceLock`; subsequent calls
//! are free.

pub mod raw_http;
pub mod wire_case;

use std::path::{Path, PathBuf};
use std::sync::OnceLock;

static WORKSPACE_ROOT: OnceLock<PathBuf> = OnceLock::new();

/// Returns the absolute path to the monorepo root.
///
/// Panics if `pnpm-workspace.yaml` cannot be found above
/// `CARGO_MANIFEST_DIR` (tests MUST run from within the monorepo).
#[allow(dead_code)]
pub fn workspace_root() -> &'static Path {
    WORKSPACE_ROOT
        .get_or_init(|| {
            let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
            let mut dir: &Path = &manifest;
            loop {
                if dir.join("pnpm-workspace.yaml").is_file() {
                    return dir.to_path_buf();
                }
                match dir.parent() {
                    Some(p) if p != dir => dir = p,
                    _ => panic!(
                        "common::workspace_root: could not find pnpm-workspace.yaml \
                         above {} (tests must run from within the monorepo)",
                        manifest.display()
                    ),
                }
            }
        })
        .as_path()
}

/// Absolute path to the 58-tuple parity corpus.
#[allow(dead_code)]
pub fn parity_corpus_path() -> PathBuf {
    workspace_root()
        .join("packages")
        .join("test-fixtures-sdk-parity")
        .join("fixtures")
        .join("parity-corpus.json")
}

